arguments.command:
python3 - <<'PY'
import sqlite3
p='incident/ledger.db'
db=sqlite3.connect(p)
for x in ['.schema','SELECT * FROM balances','SELECT * FROM payments','SELECT * FROM postings','PRAGMA integrity_check','PRAGMA journal_mode']:
 print('\n--',x)
 if x=='.schema':
  for r in db.execute("SELECT sql FROM sqlite_master WHERE type IN ('table','index') ORDER BY name"): print(r[0])
 else:
  try:
   for r in db.execute(x): print(r)
  except Exception as e: print(type(e),e)
PY
cat incident/exit-code.txt
wc -c incident/stdout.txt incident/stderr.txt

